import {initial,uid,question} from './model.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function defaultSetup(){return {name:'',author:'',language:'ru-RU',rounds:[{name:'Первый раунд',themes:6},{name:'Второй раунд',themes:6}],questions:5,basePrice:100,priceStep:100,multiplyPrices:true,hasFinal:true,finalThemes:7};}
export function setupErrors(c){const errors=[];const integer=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max;if(!c.name.trim())errors.push('Введите название пака.');if(!integer(c.rounds.length,1,10))errors.push('Выберите от 1 до 10 раундов.');for(const [i,r] of c.rounds.entries()){if(!r.name.trim())errors.push(`Укажите название раунда ${i+1}.`);if(!integer(r.themes,1,12))errors.push(`В раунде ${i+1} должно быть от 1 до 12 тем.`);}if(!integer(c.questions,1,10))errors.push('Выберите от 1 до 10 вопросов в теме.');if(!integer(c.basePrice,0,100000)||!integer(c.priceStep,1,100000))errors.push('Укажите корректную начальную стоимость и шаг цены.');if(c.hasFinal&&!integer(c.finalThemes,1,12))errors.push('В финале должно быть от 1 до 12 тем.');return errors;}
export function setupCounts(c){const themes=c.rounds.reduce((n,r)=>n+r.themes,0);return {themes:themes+(c.hasFinal?c.finalThemes:0),questions:themes*c.questions+(c.hasFinal?c.finalThemes:0)};}
export function buildPack(c){const errors=setupErrors(c);if(errors.length)throw Error(errors[0]);const p=initial(false);p.name=c.name.trim();p.author=c.author.trim();p.language=c.language;p.pricing={basePrice:c.basePrice,priceStep:c.priceStep,questions:c.questions,multiplyPrices:c.multiplyPrices};p.rounds=c.rounds.map((r,i)=>({id:uid(),name:r.name.trim(),type:'standard',priceMultiplier:c.multiplyPrices?null:1,themes:Array.from({length:r.themes},(_,t)=>({id:uid(),name:`Тема ${t+1}`,questions:Array.from({length:c.questions},(_,q)=>question(setupQuestionPrice(c,i,q)))}))}));if(c.hasFinal)p.rounds.push({id:uid(),name:'Финал',type:'final',themes:Array.from({length:c.finalThemes},(_,i)=>({id:uid(),name:`Финальная тема ${i+1}`,questions:[question(0)]}))});return p;}
const number=(name,value,min,max,label)=>`<label class="setup-field"><span>${label}</span><input type="number" name="${name}" value="${value}" min="${min}" max="${max}" step="1" required inputmode="numeric"></label>`;
export const setupRoundsHTML=(c,selected=0)=>{const r=c.rounds[selected];return r?`<div class="structure-selection-label">НАСТРОЙКИ ВЫБРАННОГО РАУНДА</div><label class="setup-field">Название раунда ${selected+1}<input name="roundName${selected}" value="${e(r.name)}" required maxlength="100"></label>${number(`roundThemes${selected}`,r.themes,1,12,`Тем в раунде ${selected+1}`)}`:`<div class="structure-selection-label">НАСТРОЙКИ ФИНАЛА</div>${number('finalThemes',c.finalThemes,1,12,'Тем в финале')}<p class="structure-field-note">По одному вопросу в каждой теме. Цену определяет ставка игрока.</p>`;};
// Share the same price calculation with the generated package.
export const setupQuestionPrice=(c,round,index)=>(c.basePrice+index*c.priceStep)*(c.multiplyPrices?round+1:1);
const plural=(n,one,few,many)=>n%100>=11&&n%100<=14?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;
export function setupPreviewHTML(c,selected=0,animate=false){
 const bounded=(v,min,max)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Math.floor(Number(v)))):min;
 const qCount=bounded(c.questions,1,10),finalCount=bounded(c.finalThemes,1,12);
 const roundCount=c.rounds.length+(c.hasFinal?1:0),totalQuestions=c.rounds.reduce((n,r)=>n+bounded(r.themes,1,12)*qCount,0)+(c.hasFinal?finalCount:0);
 const active=Math.min(selected,roundCount-1),isFinal=active===c.rounds.length,r=c.rounds[active],themeCount=isFinal?finalCount:bounded(r.themes,1,12),name=isFinal?'Финал':r.name||`Раунд ${active+1}`;
 return `<div class="structure-stage-top"><div><span class="structure-stage-dot"></span> Ваша игра</div><span>${roundCount} ${plural(roundCount,'экран','экрана','экранов')} · ${totalQuestions} ${plural(totalQuestions,'вопрос','вопроса','вопросов')}</span></div><nav class="structure-filmstrip" aria-label="Экраны раундов">${c.rounds.map((round,i)=>`<button type="button" data-presence-key="round-${i}" data-action="setup-select-round" data-index="${i}" ${active===i?'aria-current="true"':''}><span class="structure-tab-number">${String(i+1).padStart(2,'0')}</span><span>${e(round.name)||`Раунд ${i+1}`}</span></button>`).join('')}${c.hasFinal?`<button type="button" data-presence-key="final" data-action="setup-select-round" data-index="${c.rounds.length}" ${isFinal?'aria-current="true"':''}><span class="structure-tab-number">⚑</span><span>Финал</span></button>`:''}</nav><section class="structure-game-screen ${isFinal?'is-final':''}" aria-label="Предпросмотр: ${e(name)}"><div class="structure-screen-heading"><div><span>ЭКРАН ${String(active+1).padStart(2,'0')}</span><h2 id="structure-preview-title">${e(name)}</h2></div><span>${themeCount} ${plural(themeCount,'тема','темы','тем')} · ${isFinal?'по одному вопросу':`${qCount} ${plural(qCount,'вопрос','вопроса','вопросов')} в каждой`}</span></div><div class="structure-screen-scroll"><div class="structure-board">${Array.from({length:themeCount},(_,t)=>`<div class="structure-theme-row ${animate?'is-entering':''}" data-presence-key="theme-${t}" data-theme-index="${t}" style="--theme-index:${t}"><span>Тема ${t+1}</span><div class="structure-question-row" style="--question-count:${isFinal?1:qCount}">${isFinal?`<span class="structure-price stake-cell ${animate?'is-entering':''}" data-presence-key="price-0" data-price-index="0">Ставка</span>`:Array.from({length:qCount},(_,q)=>`<span class="structure-price ${animate?'is-entering':''}" data-presence-key="price-${q}" data-price-index="${q}" style="--price-index:${q}">${Number.isFinite(setupQuestionPrice(c,active,q))?setupQuestionPrice(c,active,q):'—'}</span>`).join('')}</div></div>`).join('')}</div></div><div class="structure-screen-footer"><span>СВОЯ ИГРА</span><span aria-hidden="true">✦</span></div></section><p class="structure-stage-hint">${isFinal?'Финальный экран: игроки исключают темы до последней и делают скрытые ставки.':'Выберите экран сверху, чтобы настроить его название и количество тем.'}</p>`;
}
export function setupHTML(c,stage,hasDraft,oldName,selected=0){const count=setupCounts(c),names=['О вашей игре','Структура пака','Всё готово'];return `<div class="setup-page ${stage===1?'structure-layout':''}"><header class="welcome-header"><a class="brand" href="./" data-action="setup-cancel" aria-label="Вернуться в меню"><img class="brand-logo" src="./assets/logo-horizontal.png" alt="SIGameMaker"></a><button class="setup-exit" data-action="setup-cancel">Отмена</button></header><main class="setup-main ${stage===1?'has-structure-preview':''}"><nav aria-label="Шаги создания пака"><ol class="setup-progress">${names.map((n,i)=>`<li ${i===stage?'aria-current="step"':''} class="${i<stage?'done':''}"><span>${i<stage?'✓':i+1}</span>${n}</li>`).join('')}</ol></nav><div class="setup-heading"><p>ШАГ ${stage+1} ИЗ 3</p><h1>${['Как назовём вашу игру?','Спроектируем вашу игру','Посмотрите, что получилось'][stage]}</h1><p>${['Задайте настроение вечеру. Остальное соберём по шагам.','Настройте размер пака и посмотрите, как он будет выглядеть на игровом столе.','Проверьте структуру, прежде чем переходить к вопросам.'][stage]}</p></div><form id="setup-form" data-stage="${stage}" class="setup-form ${stage===1?'with-structure-preview':''}">${stage===0?`<label class="setup-field">Название пака<input name="name" value="${e(c.name)}" placeholder="Например, Вечер пятницы" maxlength="150" required autocomplete="off" autofocus></label><div class="setup-two-columns"><label class="setup-field">Автор <span class="optional-label">Необязательно</span><input name="author" value="${e(c.author)}" placeholder="Как вас представить?" maxlength="150" autocomplete="name"></label><label class="setup-field">Язык вопросов<select name="language"><option value="ru-RU" ${c.language==='ru-RU'?'selected':''}>Русский</option><option value="en-US" ${c.language==='en-US'?'selected':''}>English</option></select></label></div>`:stage===1?`<div class="setup-structure-fields"><div class="structure-settings-header"><h2>Размер игры</h2><p>Сначала основа, затем каждый раунд.</p></div><div class="setup-two-columns">${number('roundCount',c.rounds.length,1,10,'Раундов')}${number('questions',c.questions,1,10,'Вопросов в теме')}</div><label class="setup-toggle structure-final-toggle"><input name="hasFinal" type="checkbox" ${c.hasFinal?'checked':''}><span><strong>Добавить финал</strong></span></label><section class="setup-rounds" aria-label="Настройки выбранного раунда">${setupRoundsHTML(c,selected)}</section><details class="setup-prices"><summary>Стоимость вопросов</summary><div class="setup-two-columns">${number('basePrice',c.basePrice,0,100000,'Первая цена')}${number('priceStep',c.priceStep,1,100000,'Шаг цены')}</div><label class="setup-checkbox"><input name="multiplyPrices" type="checkbox" ${c.multiplyPrices?'checked':''}> Умножать цены на номер раунда</label></details></div><aside id="setup-structure-preview" class="structure-preview" aria-labelledby="structure-preview-title">${setupPreviewHTML(c,selected,true)}</aside>`:`<section class="setup-review"><div class="setup-review-name"><h2>${e(c.name)}</h2><button type="button" data-action="setup-edit" data-stage="0">Изменить</button></div><p>${e(c.author)||'Автор не указан'} · ${c.language==='ru-RU'?'Русский':'English'}</p><div class="setup-review-stats"><div><strong>${c.rounds.length}${c.hasFinal?' + финал':''}</strong><span>Раунды</span></div><div><strong>${count.themes}</strong><span>Всего тем</span></div><div><strong>${count.questions}</strong><span>Всего вопросов</span></div></div><ul>${c.rounds.map(r=>`<li><span>${e(r.name)}</span><span>${r.themes} × ${c.questions} вопросов</span></li>`).join('')}${c.hasFinal?`<li><span>Финал</span><span>${c.finalThemes} тем × 1 вопрос</span></li>`:''}</ul><button class="setup-edit-structure" type="button" data-action="setup-edit" data-stage="1">Изменить структуру</button></section>${hasDraft?`<p class="replace-draft-note">После нажатия «Создать пак» черновик «${e(oldName)}» будет заменён. Если нужна отдельная копия, вернитесь в меню и скачайте его.</p>`:''}`}${stage===1?'<div class="structure-bottom-bar">':''}<p class="setup-reassurance"><span aria-hidden="true">↺</span> Название, раунды, темы, вопросы и цены можно изменить позже.</p><div class="setup-buttons"><button type="button" class="secondary" data-action="${stage?'setup-back':'setup-cancel'}">${stage?'← Назад':'В меню'}</button><button type="submit" class="primary">${stage===2?'Создать пак':'Далее →'}</button></div>${stage===1?'</div>':''}</form></main><footer class="setup-footer">Пока вы настраиваете игру, текущий черновик остаётся на месте.</footer></div>`;}
